def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """
    def decorator(func):
        def wrapper(*args, **kwargs):
            if lock:
                with lock:
                    if key in cache:
                        return cache[key]
                    else:
                        result = func(*args, **kwargs)
                        cache[key] = result
                        return result
            else:
                if key in cache:
                    return cache[key]
                else:
                    result = func(*args, **kwargs)
                    cache[key] = result
                    return result
        return wrapper
    return decorator

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """

    def decorator(func):
        cache = {}
        hits = misses = 0
        root = []
        timer = timer()

        def make_key(args, kwargs):
            if typed:
                return (func, args, kwargs)
            else:
                return (func, args)

        def wrapper(*args, **kwargs):
            nonlocal hits, misses
            key = make_key(args, kwargs)
            now = timer()
            try:
                value, expire = cache[key]
                if now < expire:
                    hits += 1
                    return value
                else:
                    misses += 1
            except KeyError:
                misses += 1

            value = func(*args, **kwargs)
            expire = now + ttl
            cache[key] = (value, expire)
            root.append(key)
            if len(root) > maxsize:
                root.pop(0)
            return value

        def clear():
            cache.clear()
            root.clear()

        wrapper.hits = hits
        wrapper.misses = misses
        wrapper.clear = clear
        return wrapper

    return decorator

def lru_cache(maxsize=128, typed=False):
    def decorator(func):
        cache = {}
        queue = []
        def wrapper(*args, **kwargs):
            key = (args, tuple(kwargs.items())) if typed else args
            if key in cache:
                return cache[key]
            result = func(*args, **kwargs)
            cache[key] = result
            if len(cache) > maxsize:
                queue.append(key)
                del cache[queue.pop(0)]
            return result
        return wrapper
    return decorator

def lfu_cache(maxsize=128, typed=False):
    def decorator(func):
        cache = {}
        use_count = {}
        hits = misses = 0

        def wrapper(*args, **kwargs):
            nonlocal hits, misses
            key = (args, frozenset(kwargs.items())) if typed else args
            if key in cache:
                use_count[key] += 1
                hits += 1
                return cache[key]
            else:
                misses += 1
                result = func(*args, **kwargs)
                cache[key] = result
                use_count[key] = 1
                if len(cache) > maxsize:
                    # purge least frequently used cache entry
                    to_remove = min(use_count, key=use_count.get)
                    del cache[to_remove], use_count[to_remove]
                return result

        wrapper.cache_info = lambda: (len(cache), hits, misses)
        wrapper.cache_clear = lambda: cache.clear()
        return wrapper

    return decorator

def popitem(self):
    """Remove and return the `(key, value)` pair first inserted."""
    if len(self) == 0:
        raise KeyError("popitem(): dictionary is empty")
    else:
        key = next(iter(self))
        value = self[key]
        del self[key]
        return (key, value)

def setdefault(self, key, default=None):
    if key not in self:
        self[key] = default
    return self.get(key, default)

def get(self, key, default=None):
    """
    D.get(k[,d]) -> D[k] if k in D, else d.  d defaults to None.
    """
    if key in self:
        return self[key]
    else:
        return default

def cachedmethod(cache, key=hashkey, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.

    """
    def decorator(func):
        def wrapper(*args, **kwargs):
            if lock:
                with lock:
                    key = key(*args, **kwargs)
                    if key not in cache:
                        cache[key] = func(*args, **kwargs)
            else:
                key = key(*args, **kwargs)
                if key not in cache:
                    cache[key] = func(*args, **kwargs)
            return cache[key]
        return wrapper
    return decorator

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    bases = []
    for cls in classes:
        if cls not in bases:
            bases.append(cls)
    return bases

def namesAndDescriptions(self, all=False):
    """Return attribute names and descriptions defined by interface."""
    names = []
    descriptions = []
    for name, attr in self.__class__.__dict__.items():
        if isinstance(attr, Attribute):
            names.append(name)
            descriptions.append(attr.description)
    if all:
        for base in self.__class__.__bases__:
            names.extend(base.namesAndDescriptions(all))
            descriptions.extend(base.namesAndDescriptions(all))
    return names, descriptions

def names(self, all=False):
    """Return the attribute names defined by the interface."""
    return [attr.name for attr in self.attributes if all or not attr.is_inherited]

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []
    for arg in sequence:
        if isinstance(arg, Declaration):
            output.append(arg)
        elif isinstance(arg, tuple):
            output.extend(arg)
        elif isinstance(arg, Interface):
            output.append(arg)
        elif isinstance(arg, ImplementsSpec):
            output.append(arg)
        else:
            raise ValueError("Invalid argument type: " + str(type(arg)))
    return output

