def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    if extract_spec_version:
        if inventory.type:
            try:
                spec_version = int(inventory.type.split("-")[1])
            except (ValueError, IndexError):
                spec_version = self.spec_version
        else:
            spec_version = self.spec_version
    else:
        spec_version = self.spec_version

    # Validate the inventory
    if not inventory.id:
        raise ValueError("Inventory must have an id")
    if not inventory.type:
        raise ValueError("Inventory must have a type")
    if not inventory.version:
        raise ValueError("Inventory must have a version")
    if not inventory.description:
        raise ValueError("Inventory must have a description")
    if not inventory.items:
        raise ValueError("Inventory must have at least one item")

    # Validate the items
    for item in inventory.items:
        if not item.id:
            raise ValueError("Item must have an id")
        if not item.name:
            raise ValueError("Item must have a name")
        if not item.description:
            raise ValueError("Item must have a description")
        if not item.quantity:
            raise ValueError("Item must have a quantity")
        if not item.price:
            raise ValueError("Item must have a price")

    # Validate the version
    if spec_version == 1:
        if not inventory.version.startswith("1."):
            raise ValueError("Inventory version must start with '1.'")
    elif spec_version == 2:
        if not inventory.version.startswith("2."):
            raise ValueError("Inventory version must start with '2.'")
    else:
        raise ValueError("Invalid specification version")

    return True

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    for manifest_file in manifest_files:
        with open(manifest_file, "r") as f:
            manifest = json.load(f)
        for digest in manifest["digests"]:
            if digest not in digests_used:
                raise ValueError(f"Digest {digest} is not used in the manifest file {manifest_file}")
    for digest in digests_used:
        if digest not in manifest["digests"]:
            raise ValueError(f"Digest {digest} is not present in the manifest file {manifest_file}")

