        raise ValueError("Unsupported style: " + style)

    # Check if the pieces are valid
    if not isinstance(pieces, list):
        raise TypeError("pieces must be a list")
    for piece in pieces:
        if not isinstance(piece, VersionPiece):
            raise TypeError("piece must be a VersionPiece")

    # Render the pieces
    rendered_pieces = []
    for piece in pieces:
        rendered_pieces.append(piece.render(style))

    # Return the rendered pieces
    return rendered_pieces

