            if k not in result:
                result[k] = v
            else:
                result[k] += v
    return result

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""
    if not url_args:
        return url
    for key, value in url_args.items():
        url = url.replace("{" + key + "}", value)
    return url

def is_none_string(val: any) -> bool:
    """Check if a string represents a None value."""
    return val == "None"

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    if not isinstance(string, str):
        raise ValueError("Input must be a string")
    if not isinstance(alphabet, list):
        raise ValueError("Alphabet must be a list of strings")
    if len(string) == 0:
        raise ValueError("Input string cannot be empty")
    if len(alphabet) == 0:
        raise ValueError("Alphabet cannot be empty")

    result = 0
    for i, char in enumerate(string):
        if char not in alphabet:
            raise ValueError(f"Character '{char}' is not in the alphabet")
        result += alphabet.index(char) * (len(alphabet) ** (len(string) - i - 1))

    return result

def unquote(name):
    """Remove quote from the given name."""
    return re.sub(r'^"|"$', '', name)

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """

    if platform == 'this':
        if os.name == 'nt':
            platform = 0
        else:
            platform = 1

    if platform == 0:
        # Windows/CMD
        pattern = r'((?:"[^"]*")|(?:\'[^\']*\')|(?:[^\s\'"]+))+'
    elif platform == 1:
        # POSIX
        pattern = r'((?:"[^"]*")|(?:\'[^\']*\')|(?:[^\s\'"]+))+'
    else:
        raise ValueError('Invalid platform value')

    return re.findall(pattern, s)

def prepare_repository_from_archive(archive_path, filename=None, tmp_path="/tmp"):
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    if not os.path.exists(archive_path):
        raise ValueError("Archive path does not exist")

    if not os.path.isfile(archive_path):
        raise ValueError("Archive path is not a file")

    if not os.access(archive_path, os.R_OK):
        raise ValueError("Archive path is not readable")

    if not os.path.exists(tmp_path):
        raise ValueError("Temporary path does not exist")

    if not os.path.isdir(tmp_path):
        raise ValueError("Temporary path is not a directory")

    if not os.access(tmp_path, os.W_OK):
        raise ValueError("Temporary path is not writable")

    if filename is not None and not isinstance(filename, str):
        raise ValueError("Filename must be a string")

    if filename is not None and not os.path.isabs(filename):
        raise ValueError("Filename must be an absolute path")

    if filename is not None and not os.path.exists(filename):
        raise ValueError("Filename does not exist")

    if filename is not None and not os.path.isfile(filename):
        raise ValueError("Filename is not a file")

    if filename is not None and not os.access(filename, os.R_OK):
        raise ValueError("Filename is not readable")

    # Uncompress the archive
    subprocess.run(["tar", "-xzf", archive_path, "-C", tmp_path])

    # Get the file repo url
    repo_url = subprocess.check_output(["git", "config", "--get", "remote.origin.url"], cwd=tmp_path).decode().strip()

    return repo_url

def addignored(ignored):
    """Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma."""
    ignored_files = subprocess.check_output(['git', 'ls-files', '--ignored', '--exclude-standard']).decode().splitlines()
    ignored_files.sort()
    return ','.join(ignored_files)

def parse_frequency(frequency):
    if frequency is None or frequency == "always":
        return None
    else:
        match = re.match(r"(\d+) (\w+)", frequency)
        if match:
            num = int(match.group(1))
            unit = match.group(2)
            if unit == "weeks":
                return datetime.timedelta(weeks=num)
            elif unit == "days":
                return datetime.timedelta(days=num)
            elif unit == "hours":
                return datetime.timedelta(hours=num)
            elif unit == "minutes":
                return datetime.timedelta(minutes=num)
            elif unit == "seconds":
                return datetime.timedelta(seconds=num)
            else:
                raise ValueError("Invalid frequency unit: " + unit)
        else:
            raise ValueError("Invalid frequency format: " + frequency)

def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    if not overwrite and os.path.exists(config_filename):
        raise FileExistsError("File already exists and overwrite is False")
    os.makedirs(os.path.dirname(config_filename), exist_ok=True)
    with open(config_filename, "w", mode) as f:
        f.write(rendered_config)

def _resolve_string(matcher):
    """
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    """
    name = matcher.group(1)
    default = matcher.group(2)
    if name in os.environ:
        return os.environ[name]
    elif default is not None:
        return default
    else:
        raise ValueError(f"The environment variable {name} is not defined and no default value was provided.")

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if isinstance(commands, str):
        commands = [commands]
    if isinstance(args, str):
        args = [args]
    if cwd is not None:
        os.chdir(cwd)
    if env is not None:
        os.environ.update(env)
    for command in commands:
        if verbose:
            print(command)
        if hide_stderr:
            subprocess.run(command, args, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL)
        else:
            subprocess.run(command, args, stdout=subprocess.PIPE)

