def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    if isinstance(request, PublicMessage):
        return True
    elif isinstance(request, PrivateMessage):
        return True
    elif isinstance(request, LegacyPayload):
        return True
    else:
        return False

def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    tags = set()
    code_block = False
    for word in text.split():
        if word == "```":
            code_block = not code_block
        elif not code_block and word.startswith("#"):
            tags.add(word[1:])
            if replacer:
                text = text.replace(word, replacer(word))
    return tags, text

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    links = re.findall(r"\[([^\]]+)\]\(([^)]+)\)", text)
    for link in links:
        text = text.replace(link[0], f"<a href='{link[1]}'>{link[0]}</a>")
    return text

def fetch_content_type(url: str) -> Optional[str]:
    """
    Fetch the HEAD of the remote url to determine the content type.
    """
    try:
        response = requests.head(url)
        content_type = response.headers.get("Content-Type")
        return content_type
    except requests.exceptions.RequestException:
        return None

