def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if document.startswith('<?xml'):
        # Parse XRD format
        root = ET.fromstring(document)
        ns = {'xrd': 'http://docs.oasis-open.org/ns/xri/xrd-1.0'}
        xrd = root.find('xrd:XRD', ns)
        if xrd is None:
            raise ValueError('Invalid XRD format')
        webfinger = {}
        for subject in xrd.findall('xrd:Subject', ns):
            webfinger[subject.text] = {}
            for property in subject.findall('xrd:Property', ns):
                webfinger[subject.text][property.attrib['name']] = property.text
        return webfinger
    else:
        # Parse JSON format
        webfinger = json.loads(document)
        if 'subject' not in webfinger or 'properties' not in webfinger:
            raise ValueError('Invalid JSON format')
        return webfinger

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    try:
        response = requests.get(f"https://{handle}.webfinger")
        if response.status_code == 200:
            return response.text
        else:
            return None
    except requests.exceptions.RequestException:
        return None

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    response = requests.get(handle)
    if response.status_code == 200:
        return json.loads(response.text)
    else:
        raise Exception("Error retrieving Diaspora webfinger document: " + response.text)

def retrieve_diaspora_host_meta(host):
    """
    Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from
    :returns: ``XRD`` instance
    """
    import requests
    url = "https://" + host + "/host-meta"
    response = requests.get(url)
    if response.status_code == 200:
        return XRD(response.text)
    else:
        raise Exception("Unable to retrieve host-meta document from " + host)

